"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["68757"],{96048(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.impedimento_sem_condicao","status":422,"titulo":"O impedimento do campo n\xe3o tem condi\xe7\xe3o"},"descricao":{"codigo":"uniplus.item_formulario.impedimento_sem_condicao","requisitos":[],"oQueAconteceu":["O `impedimento` de um item traz `quando` ausente, nulo ou como lista vazia. A condi\xe7\xe3o \xe9 a lista de cl\xe1usulas (o OU de cl\xe1usulas, cada uma o E de condi\xe7\xf5es) que diz em que resposta do campo a inscri\xe7\xe3o fica impedida; sem cl\xe1usula, nenhuma resposta impediria. A mensagem \xe9 \\"O impedimento tem a condi\xe7\xe3o sobre a resposta do campo.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].impedimento.quando` ou, no campo de um grupo, `grupos[g].subitens[j].impedimento.quando`; nos modelos de formul\xe1rio come\xe7a por `conteudo.`. Ela sai na leitura do item, junto com as demais recusas de leitura: o item recusado n\xe3o segue para a confer\xeancia contra o cat\xe1logo, e, no modelo de formul\xe1rio, o conte\xfado com recusa de leitura n\xe3o chega \xe0s regras que dependem dele inteiro, como a forma dos itens, e as recusas do cadastro (c\xf3digo, nome, descri\xe7\xe3o, tipo de processo) saem junto. Nada \xe9 gravado. No campo de um grupo repet\xedvel a causa \xe9 a mesma e vem no caminho do campo. Na grava\xe7\xe3o dos itens do formul\xe1rio, o campo de grupo com impedimento \xe9 recusado tamb\xe9m como [campo de grupo com impedimento](/erros/uniplus.grupo_formulario.campo_com_impedimento); nos modelos, o grupo que tem campo recusado na leitura sai do conte\xfado conferido, e s\xf3 esta recusa de leitura aponta o campo. Na atualiza\xe7\xe3o de um modelo, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado).","A condi\xe7\xe3o com uma cl\xe1usula vazia \xe9 outra recusa, a de forma da condi\xe7\xe3o, e a condi\xe7\xe3o que n\xe3o cita o pr\xf3prio campo \xe9 a de [impedimento sem o pr\xf3prio campo](/erros/uniplus.item_formulario.impedimento_sem_o_proprio_campo)."],"comoResolver":["Informe em `impedimento.quando` ao menos uma cl\xe1usula com a condi\xe7\xe3o sobre a resposta do campo, ou retire o `impedimento` do item."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);